#![cfg(feature = "decision-clef")]

//! Clef-flash against the checkpoint's own Python code (`fixtures/clef-flash.json`, generated by
//! `tools/generate_clef_reference.py`).
//!
//! AUDIOGRAPH_CLEF_DIR is the checkpoint directory (a `Cloudflare/clef-flash` snapshot);
//! AUDIOGRAPH_CLEF_EP selects `cpu` (default) or `cuda-f32` (FP32 compute on the stored BF16 weights,
//! compared with the FP32 reference), or `cuda` (BF16, compared with the published BF16 path).

use audio_graph_decision_engine::DecisionRequest;
use audio_graph_decision_engine::clef::{ClefModel, format};
use candle_core::{DType, Device};
use serde_json::Value;

const FP32_TOLERANCE: f64 = 1e-3;
const BF16_TOLERANCE: f64 = 5e-2;
const BF16_PICK_MARGIN: f64 = 0.05;

fn floats(v: &Value) -> Vec<f64> {
    v.as_array()
        .unwrap()
        .iter()
        .map(|x| x.as_f64().unwrap())
        .collect()
}

fn argmax(p: &[f64]) -> usize {
    (1..p.len()).fold(0, |best, i| if p[i] > p[best] { i } else { best })
}

fn margin(p: &[f64]) -> f64 {
    let mut sorted = p.to_vec();
    sorted.sort_by(|a, b| b.total_cmp(a));
    sorted[0] - sorted.get(1).copied().unwrap_or(0.0)
}

#[test]
#[ignore = "requires AUDIOGRAPH_CLEF_DIR with a Cloudflare/clef-flash snapshot"]
fn clef_flash_matches_the_reference() {
    let root = std::path::PathBuf::from(
        std::env::var_os("AUDIOGRAPH_CLEF_DIR").expect("set AUDIOGRAPH_CLEF_DIR"),
    );
    let (device, dtype, field) = match std::env::var("AUDIOGRAPH_CLEF_EP").as_deref() {
        #[cfg(feature = "cuda")]
        Ok("cuda") => (Device::new_cuda(0).unwrap(), DType::BF16, "official"),
        #[cfg(feature = "cuda")]
        Ok("cuda-f32") => (Device::new_cuda(0).unwrap(), DType::F32, "fp32"),
        _ => (Device::Cpu, DType::F32, "fp32"),
    };
    let model = ClefModel::load(&root, dtype, &device).unwrap();
    let fixture: Value = serde_json::from_str(include_str!("../fixtures/clef-flash.json")).unwrap();
    let (mut questions, mut worst, mut flips) = (0, 0f64, 0);
    for case in fixture["cases"].as_array().unwrap() {
        let id = case["id"].as_str().unwrap();
        let request: DecisionRequest = serde_json::from_value(case["request"].clone()).unwrap();
        let encoded =
            format::encode(model.tokenizer(), &request.state, &request.questions).unwrap();
        let expected_ids: Vec<u32> = case["input_ids"]
            .as_array()
            .unwrap()
            .iter()
            .map(|v| v.as_u64().unwrap() as u32)
            .collect();
        assert_eq!(encoded.input_ids, expected_ids, "{id}: token ids");
        let started = std::time::Instant::now();
        let scored = model.score_encoded(encoded).unwrap();
        let elapsed = started.elapsed().as_secs_f64();
        for (q, (eq, probs)) in case["questions"]
            .as_array()
            .unwrap()
            .iter()
            .zip(scored.encoded.questions.iter().zip(&scored.probabilities))
        {
            let qid = q["id"].as_str().unwrap();
            assert_eq!(eq.id, qid);
            let spans: Vec<(usize, usize)> = q["option_spans"]
                .as_array()
                .unwrap()
                .iter()
                .map(|s| {
                    (
                        s[0].as_u64().unwrap() as usize,
                        s[1].as_u64().unwrap() as usize,
                    )
                })
                .collect();
            assert_eq!(eq.option_spans, spans, "{id}/{qid}: option spans");
            let option_ids: Vec<String> = serde_json::from_value(q["option_ids"].clone()).unwrap();
            assert_eq!(eq.option_ids, option_ids, "{id}/{qid}: option order");
            let got: Vec<f64> = probs.iter().map(|p| f64::from(*p)).collect();
            let reference = floats(&q[field]);
            let diff = got
                .iter()
                .zip(&reference)
                .map(|(a, b)| (a - b).abs())
                .fold(0.0, f64::max);
            worst = worst.max(diff);
            questions += 1;
            let pick_matches = argmax(&got) == argmax(&reference);
            if dtype == DType::F32 {
                assert!(
                    diff <= FP32_TOLERANCE,
                    "{id}/{qid}: |p - p_fp32| = {diff:e}"
                );
                assert!(pick_matches, "{id}/{qid}: pick");
            } else {
                assert!(
                    diff <= BF16_TOLERANCE,
                    "{id}/{qid}: |p - p_official| = {diff:e}"
                );
                if !pick_matches {
                    flips += 1;
                    assert!(margin(&reference) <= BF16_PICK_MARGIN, "{id}/{qid}: pick");
                }
            }
            // The contract answer reports the probability of its own pick.
            let question = &request.questions[qid];
            format::answer(question, eq, probs).unwrap();
        }
        println!(
            "{id}: {} tokens, forward+head {elapsed:.2}s",
            scored.encoded.input_ids.len()
        );
    }
    println!(
        "clef-flash {dtype:?} on {device:?}: {questions} questions, max |p - p_{field}| = {worst:.3e}, near-tie flips {flips}"
    );
    assert!(questions >= 20);
}
